-- SQLite 3.25+; run from the retail-sales directory.
-- Rebuilds this project database only. All data is simulated and supplied here.
DROP VIEW IF EXISTS clean_sales;
DROP VIEW IF EXISTS valid_sales;
DROP VIEW IF EXISTS rejected_rows;
DROP VIEW IF EXISTS staged_sales;
DROP VIEW IF EXISTS ranked_sales;
DROP TABLE IF EXISTS raw_sales;
CREATE TABLE raw_sales (
  source_row INTEGER PRIMARY KEY,
  transaction_id TEXT, order_date TEXT, city TEXT, category TEXT, product TEXT,
  channel TEXT, quantity TEXT, unit_price_ngn TEXT, unit_cost_ngn TEXT,
  discount_rate TEXT, status TEXT
);
BEGIN TRANSACTION;
COMMIT;
